#pragma once
#include <vector>
#include <array>
#include <algorithm>
#include <cmath>
#include <cstdint>
// Image-space optics. The caller supplies actual pixels behind the surface.
// No desktop capture, static artwork or window ownership lives in this module.
namespace liquidfx {
struct Profile {float radius=10,blur=4,bend=7,edge=18,tint=.12f;bool dark=false;};
inline float sdf(float x,float y,int width,int height,float radius){float qx=std::abs(x-width*.5f)-(width*.5f-radius),qy=std::abs(y-height*.5f)-(height*.5f-radius);return std::sqrt(std::max(qx,0.f)*std::max(qx,0.f)+std::max(qy,0.f)*std::max(qy,0.f))+std::min(std::max(qx,qy),0.f)-radius;}
inline float channel(uint32_t pixel,int c){return float((pixel>>(c*8))&255);}
inline std::array<float,3> sample(const std::vector<uint32_t>&pixels,int w,int h,float x,float y){x=std::clamp(x,0.f,float(w-1));y=std::clamp(y,0.f,float(h-1));int ix=int(x),iy=int(y),jx=std::min(ix+1,w-1),jy=std::min(iy+1,h-1);float a=x-ix,b=y-iy;std::array<float,3> result{};for(int c=0;c<3;++c)result[c]=(channel(pixels[iy*w+ix],c)*(1-a)+channel(pixels[iy*w+jx],c)*a)*(1-b)+(channel(pixels[jy*w+ix],c)*(1-a)+channel(pixels[jy*w+jx],c)*a)*b;return result;}
inline void boxPass(const std::vector<uint32_t>&in,std::vector<uint32_t>&out,int w,int h,int radius,bool vertical){out.resize(in.size());int lines=vertical?w:h,length=vertical?h:w;auto index=[&](int line,int pos){return vertical?pos*w+line:line*w+pos;};for(int line=0;line<lines;++line){int sums[3]{};for(int k=-radius;k<=radius;++k){auto p=in[index(line,std::clamp(k,0,length-1))];for(int c=0;c<3;++c)sums[c]+=int(channel(p,c));}for(int pos=0;pos<length;++pos){uint32_t p=0xff000000;for(int c=0;c<3;++c)p|=uint32_t(sums[c]/(2*radius+1))<<(c*8);out[index(line,pos)]=p;auto remove=in[index(line,std::clamp(pos-radius,0,length-1))],add=in[index(line,std::clamp(pos+radius+1,0,length-1))];for(int c=0;c<3;++c)sums[c]+=int(channel(add,c)-channel(remove,c));}}}
inline bool render(const std::vector<uint32_t>&source,int w,int h,Profile look,std::vector<uint32_t>&output){if(w<2||h<2||w>4096||h>4096||source.size()!=size_t(w)*h)return false;look.radius=std::clamp(look.radius,0.f,std::min(w,h)*.5f);look.bend=std::clamp(look.bend,0.f,40.f);look.edge=std::max(1.f,look.edge);look.tint=std::clamp(look.tint,0.f,1.f);std::vector<uint32_t> blurred=source,scratch;int radius=std::clamp(int(std::lround(look.blur*.58f)),0,24);if(radius)for(int i=0;i<3;++i){boxPass(blurred,scratch,w,h,radius,false);boxPass(scratch,blurred,w,h,radius,true);}output.resize(source.size());
    for(int y=0;y<h;++y)for(int x=0;x<w;++x){float px=x+.5f,py=y+.5f,d=sdf(px,py,w,h,look.radius);if(d>0){output[y*w+x]=source[y*w+x]|0xff000000;continue;}float qx=std::abs(px-w*.5f)-(w*.5f-look.radius),qy=std::abs(py-h*.5f)-(h*.5f-look.radius),signX=px>=w*.5f?1.f:-1.f,signY=py>=h*.5f?1.f:-1.f,nx=qx>qy?signX:0,ny=qx>qy?0:signY;if(qx>0&&qy>0){float length=std::sqrt(qx*qx+qy*qy);nx=signX*qx/length;ny=signY*qy/length;}float edge=std::pow(std::clamp(1+d/look.edge,0.f,1.f),2),bend=look.bend*edge;float zoom=look.bend>0?1.018f:1.f,sx=(px-w*.5f)/zoom+w*.5f-.5f-nx*bend,sy=(py-h*.5f)/zoom+h*.5f-.5f-ny*bend;auto rgb=sample(blurred,w,h,sx,sy);auto clear=sample(source,w,h,sx,sy);float clarity=edge*.72f;for(int c=0;c<3;++c)rgb[c]+=(clear[c]-rgb[c])*clarity;float lighting=std::clamp(-nx*.65f-ny*.75f,0.f,1.f),rim=std::pow(std::clamp(1+d/2.f,0.f,1.f),2);uint32_t pixel=0xff000000;for(int c=0;c<3;++c){float value=rgb[c]*(1-look.tint)+(look.dark?23.f:247.f)*look.tint;value+=rim*(20+lighting*46);value-=edge*(1-lighting)*5;pixel|=uint32_t(std::lround(std::clamp(value,0.f,255.f)))<<(c*8);}output[y*w+x]=pixel;}return true;
}
inline bool test(){int w=96,h=64;std::vector<uint32_t>pixels(w*h,0xff64788c),out;Profile look;look.blur=0;look.bend=0;look.tint=0;if(!render(pixels,w,h,look,out)||out[(h/2)*w+w/2]!=pixels[0])return false;for(int y=0;y<h;++y)for(int x=0;x<w;++x)pixels[y*w+x]=0xff000000|((x/8+y/8)%2?0xffffff:0);look.bend=9;look.tint=0;std::vector<uint32_t>bent;if(!render(pixels,w,h,look,bent)||bent==pixels)return false;look.bend=0;look.blur=5;std::vector<uint32_t>soft;if(!render(pixels,w,h,look,soft)||soft==pixels)return false;for(auto p:soft)if((p>>24)!=255)return false;return !render({},w,h,look,out);}
}
